CREATE ROLE anon;
CREATE ROLE authenticated;
CREATE ROLE service_role BYPASSRLS;
CREATE TABLE public.alert_rules (id uuid NOT NULL DEFAULT gen_random_uuid(), user_id uuid, categorie text, fridge_days integer, freezer_days integer);
CREATE TABLE public.app_users (id uuid NOT NULL DEFAULT gen_random_uuid(), created_at timestamp with time zone DEFAULT now(), username text NOT NULL, password text NOT NULL);
CREATE TABLE public.categories (id uuid NOT NULL DEFAULT gen_random_uuid(), created_at timestamp with time zone DEFAULT now(), name text NOT NULL);
CREATE TABLE public.cellars (id uuid NOT NULL DEFAULT gen_random_uuid(), created_at timestamp with time zone DEFAULT now(), user_id uuid, name text NOT NULL, is_secondary boolean DEFAULT false);
CREATE TABLE public.items (id uuid NOT NULL DEFAULT gen_random_uuid(), created_at timestamp with time zone DEFAULT now(), user_id uuid, cellar_id uuid, categorie text NOT NULL, produit text NOT NULL, qte numeric DEFAULT 1, unite text DEFAULT 'Bouteille 75cl'::text, date_entree date DEFAULT CURRENT_DATE, date_peremption date, notes text, millesime text, format text, date_fabrication date, domaine text);
CREATE TABLE public.product_templates (id uuid NOT NULL DEFAULT gen_random_uuid(), created_at timestamp with time zone DEFAULT now(), category_id uuid, name text NOT NULL);
CREATE TABLE public.storage_defaults (id uuid NOT NULL DEFAULT gen_random_uuid(), created_at timestamp with time zone NOT NULL DEFAULT timezone('utc'::text, now()), user_id uuid NOT NULL, ingredient_id uuid NOT NULL, cellar_id uuid NOT NULL);
CREATE TABLE public.storage_routing_rules (id uuid NOT NULL DEFAULT gen_random_uuid(), created_at timestamp with time zone NOT NULL DEFAULT now(), user_id uuid NOT NULL, rule_type text NOT NULL, category text, ingredient_id uuid, cellar_id uuid, priority integer NOT NULL DEFAULT 100, is_active boolean NOT NULL DEFAULT true);
CREATE TABLE public.user_settings (user_id uuid NOT NULL, ntfy_topic text);
ALTER TABLE public.alert_rules ADD CONSTRAINT alert_rules_pkey PRIMARY KEY (id);
ALTER TABLE public.alert_rules ADD CONSTRAINT alert_rules_user_id_categorie_key UNIQUE (user_id, categorie);
ALTER TABLE public.app_users ADD CONSTRAINT app_users_pkey PRIMARY KEY (id);
ALTER TABLE public.app_users ADD CONSTRAINT app_users_username_key UNIQUE (username);
ALTER TABLE public.categories ADD CONSTRAINT categories_name_key UNIQUE (name);
ALTER TABLE public.categories ADD CONSTRAINT categories_pkey PRIMARY KEY (id);
ALTER TABLE public.cellars ADD CONSTRAINT cellars_id_user_id_unique UNIQUE (id, user_id);
ALTER TABLE public.cellars ADD CONSTRAINT cellars_pkey PRIMARY KEY (id);
ALTER TABLE public.cellars ADD CONSTRAINT cellars_user_id_fkey FOREIGN KEY (user_id) REFERENCES app_users(id) ON DELETE CASCADE;
ALTER TABLE public.items ADD CONSTRAINT items_cellar_id_fkey FOREIGN KEY (cellar_id) REFERENCES cellars(id) ON DELETE CASCADE;
ALTER TABLE public.items ADD CONSTRAINT items_pkey PRIMARY KEY (id);
ALTER TABLE public.items ADD CONSTRAINT items_user_id_fkey FOREIGN KEY (user_id) REFERENCES app_users(id) ON DELETE CASCADE;
ALTER TABLE public.product_templates ADD CONSTRAINT product_templates_category_id_fkey FOREIGN KEY (category_id) REFERENCES categories(id) ON DELETE CASCADE;
ALTER TABLE public.product_templates ADD CONSTRAINT product_templates_pkey PRIMARY KEY (id);
ALTER TABLE public.storage_defaults ADD CONSTRAINT storage_defaults_cellar_user_fkey FOREIGN KEY (cellar_id, user_id) REFERENCES cellars(id, user_id) ON DELETE CASCADE;
ALTER TABLE public.storage_defaults ADD CONSTRAINT storage_defaults_pkey PRIMARY KEY (id);
ALTER TABLE public.storage_defaults ADD CONSTRAINT storage_defaults_user_id_fkey FOREIGN KEY (user_id) REFERENCES app_users(id) ON DELETE CASCADE;
ALTER TABLE public.storage_defaults ADD CONSTRAINT storage_defaults_user_ingredient_unique UNIQUE (user_id, ingredient_id);
ALTER TABLE public.storage_routing_rules ADD CONSTRAINT storage_routing_rules_pkey PRIMARY KEY (id);
ALTER TABLE public.storage_routing_rules ADD CONSTRAINT storage_routing_rules_target_check CHECK ((((rule_type = 'default'::text) AND (category IS NULL) AND (ingredient_id IS NULL)) OR ((rule_type = 'category'::text) AND (category IS NOT NULL) AND (ingredient_id IS NULL)) OR ((rule_type = 'ingredient'::text) AND (ingredient_id IS NOT NULL) AND (category IS NULL))));
ALTER TABLE public.storage_routing_rules ADD CONSTRAINT storage_routing_rules_type_check CHECK ((rule_type = ANY (ARRAY['default'::text, 'category'::text, 'ingredient'::text])));
ALTER TABLE public.storage_routing_rules ADD CONSTRAINT storage_routing_rules_user_fkey FOREIGN KEY (user_id) REFERENCES app_users(id);
ALTER TABLE public.user_settings ADD CONSTRAINT user_settings_pkey PRIMARY KEY (user_id);
GRANT ALL ON ALL TABLES IN SCHEMA public TO anon,authenticated,service_role;
